16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum ItemType {
18	    Sword,
19	    Amulet,
20	    Staff,
21	    Potion,
22	    Rune,
23	    Moonstone,
24	}
25	
26	impl ItemType {
27	    /// A component -- for example a rune or a moonstone -- rather than a main
28	    /// item. The MHPCO records no curse, enchantment or material for a
29	    /// component, and charges it per group of alike ones instead of giving it
30	    /// its own price-list row.
31	    fn is_component(self) -> bool {
32	        matches!(self, Self::Rune | Self::Moonstone)
33	    }
34	
35	    /// The MHPCO price-list row for a main item, or `None` for a component:
36	    /// components are not on the main price list, they are charged per group of
37	    /// alike ones by `component_charge`.
38	    fn main_item_base_premium(self) -> Option<f64> {
39	        match self {
40	            Self::Sword => Some(100.0),
41	            Self::Amulet => Some(60.0),
42	            Self::Staff => Some(80.0),
43	            Self::Potion => Some(40.0),
44	            Self::Rune | Self::Moonstone => None,
45	        }
46	    }
47	
48	    /// The MHPCO insures each item at its price-list insurance value. This is a
49	    /// separate price-list column from `main_item_base_premium`: the MHPCO reads
50	    /// the two independently, so a premium offer such as the component block
51	    /// discount moves one and leaves the other untouched.
52	    fn insurance_value(self) -> u64 {
53	        match self {
54	            Self::Sword => 1000,
55	            Self::Amulet => 600,
56	            Self::Staff => 800,
57	            Self::Potion => 400,
58	            Self::Rune | Self::Moonstone => COMPONENT_INSURANCE_VALUE,
59	        }
60	    }
61	
62	    /// What the MHPCO calls this item type. The office reads and writes the one
63	    /// vocabulary: `parse` accepts these names from a claimant, and a notice the
64	    /// office sends back cites the item type by the same name.
65	    fn name(self) -> &'static str {
66	        match self {
67	            Self::Sword => "sword",
68	            Self::Amulet => "amulet",
69	            Self::Staff => "staff",
70	            Self::Potion => "potion",
71	            Self::Rune => "rune",
72	            Self::Moonstone => "moonstone",
73	        }
74	    }
75	
76	    pub fn parse(name: &str) -> Result<Self, String> {
77	        match name {
78	            "sword" => Ok(Self::Sword),
79	            "amulet" => Ok(Self::Amulet),
80	            "staff" => Ok(Self::Staff),
81	            "potion" => Ok(Self::Potion),
82	            "rune" => Ok(Self::Rune),
83	            "moonstone" => Ok(Self::Moonstone),
84	            unknown => Err(format!("the MHPCO does not insure items of type '{unknown}'")),
85	        }
86	    }
87	}
