89	#[derive(Clone)]
90	pub struct Item {
91	    item_type: ItemType,
92	    cursed: bool,
93	    enchantment: u32,
94	    material: String,
95	}
96	
97	impl Item {
98	    pub fn new(item_type: ItemType) -> Self {
99	        Self {
100	            item_type,
101	            cursed: false,
102	            enchantment: 0,
103	            material: String::new(),
104	        }
105	    }
106	
107	    /// The material the MHPCO recorded for this item.
108	    pub fn of_material(mut self, material: &str) -> Self {
109	        self.material = material.to_owned();
110	        self
111	    }
112	
113	    /// The item's enchantment level, as recorded by the MHPCO.
114	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
115	        self.enchantment = enchantment;
116	        self
117	    }
118	
119	    /// A cursed item carries the MHPCO's risk surcharge.
120	    pub fn cursed(mut self) -> Self {
121	        self.cursed = true;
122	        self
123	    }
124	
125	    /// The item-specific risk surcharges this item carries, charged against the
126	    /// item's own base premium rather than the policy total. A component carries
127	    /// none: the MHPCO records no curse, enchantment or material for one, so it
128	    /// is never an affected item.
129	    fn item_surcharge(&self) -> f64 {
130	        self.item_type
131	            .main_item_base_premium()
132	            .map_or(0.0, |item_base| item_base * self.risk_surcharge_rate())
133	    }
134	
135	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
136	    /// enchantment threshold when reimbursing damage, so this one is named for
137	    /// the premium it surcharges.
138	    fn is_highly_enchanted(&self) -> bool {
139	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
140	    }
141	
142	    /// The share of a damage amount the MHPCO reimburses for this item, under the
143	    /// reimbursement clauses it reads today. Only one clause reduces the share:
144	    /// damage to a very highly enchanted item is reimbursed at half. That
145	    /// enchantment threshold is a higher one than the threshold that surcharges
146	    /// the premium, and the MHPCO reads the two independently -- the level and the
147	    /// share, though, are the one clause, so they are read together here.
148	    ///
149	    /// The MHPCO's other reimbursement clause -- dragon material is reimbursed in
150	    /// full -- deliberately has no branch here. Full reimbursement is already what
151	    /// an item under no clause receives, and the half-reimbursement clause wins
152	    /// wherever both apply, so the dragon clause cannot move any share the MHPCO
153	    /// recognises. The material stays a recorded property of the item; give it a
154	    /// branch only when a clause makes it change a share.
155	    fn reimbursement_share(&self) -> f64 {
156	        if self.enchantment >= HALF_REIMBURSEMENT_LEVEL {
157	            HALF_REIMBURSEMENT
158	        } else {
159	            FULL_REIMBURSEMENT
160	        }
161	    }
162	
163	    /// Curse and high enchantment are independent risks; an item carrying both
164	    /// is surcharged for both.
165	    fn risk_surcharge_rate(&self) -> f64 {
166	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
167	        let enchantment = if self.is_highly_enchanted() {
168	            HIGH_ENCHANTMENT_SURCHARGE
169	        } else {
170	            0.0
171	        };
172	        curse + enchantment
173	    }
174	}
175	
176	const PROCESSING_FEE: u64 = 5;
177	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
178	/// Cursed items add a risk surcharge on their own base premium.
179	const CURSE_SURCHARGE: f64 = 0.50;
180	/// Long-standing customers -- 2 or more years of business with the MHPCO --
181	/// receive a loyalty discount on the policy base premium.
182	const LOYALTY_YEARS: u32 = 2;
183	const LOYALTY_DISCOUNT: f64 = 0.20;
184	/// Customers receive a discount on each contract after their first.
185	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
186	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
187	/// surcharge on their own base premium.
188	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
189	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
190	/// Components -- for example runes and moonstones -- share one price-list row.
191	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
192	
193	/// How the MHPCO settles a rated premium into the amount it bills: the rated
194	/// fraction is rounded in the MHPCO's own favour -- upwards, the larger amount
195	/// -- and the processing fee is added to every premium at the very end.
196	fn settled_premium(rated: f64) -> u64 {
197	    rated.ceil() as u64 + PROCESSING_FEE
198	}
199	
200	/// The policy-wide modifier rate, charged against the policy base premium --
201	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
202	/// against one another: a first insurance carries an initial assessment
203	/// surcharge, a long-standing customer earns a loyalty discount, and every
204	/// contract after the customer's first earns a follow-up discount.
205	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
206	    let loyalty = if customer.is_long_standing() {
207	        LOYALTY_DISCOUNT
208	    } else {
209	        0.0
210	    };
211	    let follow_up = match contract {
212	        Contract::First => 0.0,
213	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
214	    };
215	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
216	}
217	
218	/// A building block of exactly 3 alike components is offered at this price
219	/// instead of the per-component base premium.
220	const COMPONENT_BLOCK_SIZE: usize = 3;
221	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
222	
223	fn component_charge(alike_count: usize) -> f64 {
224	    if alike_count == COMPONENT_BLOCK_SIZE {
225	        COMPONENT_BLOCK_BASE_PREMIUM
226	    } else {
227	        alike_count as f64 * COMPONENT_BASE_PREMIUM
228	    }
229	}
230	
231	/// The policy's components gathered into groups of alike ones, each group
232	/// reported as its size. Alike components are the ones charged together, so the
233	/// MHPCO's reading of "alike" -- same item type -- lives here and nowhere else.
234	fn alike_component_groups(items: &[Item]) -> Vec<usize> {
235	    let mut groups: Vec<(ItemType, usize)> = Vec::new();
236	    for component in items.iter().filter(|item| item.item_type.is_component()) {
237	        match groups
238	            .iter_mut()
239	            .find(|(group_type, _)| *group_type == component.item_type)
240	        {
241	            Some((_, count)) => *count += 1,
242	            None => groups.push((component.item_type, 1)),
243	        }
244	    }
245	    groups.into_iter().map(|(_, count)| count).collect()
246	}
247	
248	/// Main items are charged one price-list row each, individually.
249	fn main_items_base_premium(items: &[Item]) -> f64 {
250	    items
251	        .iter()
252	        .filter_map(|item| item.item_type.main_item_base_premium())
253	        .sum()
254	}
255	
256	/// Components are charged per group of alike components, so that a group of
257	/// exactly 3 earns the block price.
258	fn component_blocks_base_premium(items: &[Item]) -> f64 {
259	    alike_component_groups(items)
260	        .into_iter()
261	        .map(component_charge)
262	        .sum()
263	}
264	
265	/// The policy base premium is the sum of the items' base premiums, with alike
266	/// components charged as blocks.
267	pub fn policy_base_premium(items: &[Item]) -> f64 {
268	    main_items_base_premium(items) + component_blocks_base_premium(items)
269	}
270	
271	/// Item-specific modifiers apply to the base premium of the affected item, not
272	/// to the policy total.
273	fn item_surcharges(items: &[Item]) -> f64 {
274	    items.iter().map(Item::item_surcharge).sum()
275	}
276	
277	/// A customer's first contract with the MHPCO, or any contract after it.
278	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
279	pub enum Contract {
280	    First,
281	    FollowUp,
282	}
283	
284	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
285	/// premium, modified policy-wide for the customer and the contract, plus the
286	/// surcharges carried by the individual affected items. This is the rating
287	/// decision; it is deliberately unrounded and carries no processing fee.
288	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
289	    let policy_base = policy_base_premium(items);
290	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
291	}
292	
293	/// The premium the customer is billed: the MHPCO rates the policy, then settles
294	/// the rated amount into the amount billed.
295	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
296	    settled_premium(rated_premium(customer, items, contract))
297	}
298	
299	/// Damage to an item enchanted at this level or above is reimbursed at half.
300	const HALF_REIMBURSEMENT_LEVEL: u32 = 8;
301	const HALF_REIMBURSEMENT: f64 = 0.50;
302	const FULL_REIMBURSEMENT: f64 = 1.0;
303	
304	/// Components are insured at this value each.
305	const COMPONENT_INSURANCE_VALUE: u64 = 250;
306	
307	/// The total payout per policy is capped at this multiple of its insurance sum.
308	const CAP_MULTIPLE: u64 = 2;
309	
310	/// A deductible applies per damage event, once for each damaged item.
311	const DEDUCTIBLE_PER_DAMAGE: f64 = 100.0;
312	
313	/// A single damaged item reported in an incident.
314	pub struct Damage {
315	    item_type: ItemType,
316	    amount: i64,
317	}
318	
319	impl Damage {
320	    pub fn new(item_type: ItemType, amount: i64) -> Self {
321	        Self { item_type, amount }
322	    }
323	
324	    /// What the MHPCO reimburses for this one damaged item, as an exact
325	    /// fraction: the share of the damage amount the insured item's clauses
326	    /// allow, less the deductible that applies once per damage event.
327	    fn reimbursement(&self, insured: &Item) -> f64 {
328	        self.amount as f64 * insured.reimbursement_share() - DEDUCTIBLE_PER_DAMAGE
329	    }
330	}
331	
332	/// How the MHPCO settles a reimbursed amount into the amount it pays out: the
333	/// reimbursed fraction is rounded in the MHPCO's own favour -- downwards, the
334	/// smaller amount -- which is the opposite direction from a premium.
335	fn settled_payout(reimbursed: f64) -> u64 {
336	    reimbursed.floor() as u64
337	}
338	
339	/// What the MHPCO pays out on one claim.
340	#[derive(Debug, PartialEq, Eq)]
341	pub struct Settlement {
342	    pub payout: u64,
343	    pub remaining_cap: u64,
344	}
345	
346	/// A policy the MHPCO has written over a customer's items.
347	pub struct Policy {
348	    items: Vec<Item>,
349	    remaining_cap: u64,
350	}
351	
352	/// The MHPCO's record of which insured items have already answered for a damage
353	/// within one incident. The office holds each insured item to at most one damage
354	/// per incident, so an incident reporting more damaged items of a type than the
355	/// policy insures finds no further item to answer and is rejected whole.
356	///
357	/// The ledger is the MHPCO's coverage decision, kept apart from how a damage is
358	/// reimbursed once covered: which insured item answers may come to depend on the
359	/// item's own properties, while what it reimburses is already the clauses on
360	/// `Item` and `Damage`.
361	struct CoverageLedger {
362	    answered: Vec<usize>,
363	}
364	
365	impl CoverageLedger {
366	    /// A fresh ledger: no insured item has answered yet in this incident.
367	    fn for_incident() -> Self {
368	        Self {
369	            answered: Vec::new(),
370	        }
371	    }
372	
373	    /// The insured item that answers for this damage, recorded as answered so it
374	    /// cannot answer again in this incident. Any insured item of the reported type
375	    /// that has not yet answered will do: two items of a type carry the same
376	    /// reimbursement clauses, so which one is chosen cannot move the payout.
377	    fn assign(&mut self, policy: &Policy, damage: &Damage) -> Result<usize, String> {
378	        let index = policy
379	            .items
380	            .iter()
381	            .enumerate()
382	            .position(|(index, item)| {
383	                item.item_type == damage.item_type && !self.answered.contains(&index)
384	            })
385	            .ok_or_else(|| {
386	                format!(
387	                    "the policy covers no unclaimed item of type '{}'",
388	                    damage.item_type.name()
389	                )
390	            })?;
391	        self.answered.push(index);
392	        Ok(index)
393	    }
394	}
395	
396	impl Policy {
397	    pub fn new(items: &[Item]) -> Self {
398	        Self {
399	            remaining_cap: Self::payout_cap(items),
400	            items: items.to_vec(),
401	        }
402	    }
403	
404	    /// The policy's insurance sum: the sum of the insured items' insurance
405	    /// values. Every insured item counts its own value, so two items of one type
406	    /// count twice, and a block of alike components counts each component -- the
407	    /// block discount is a premium offer and leaves the insurance sum untouched.
408	    fn insurance_sum(items: &[Item]) -> u64 {
409	        items
410	            .iter()
411	            .map(|item| item.item_type.insurance_value())
412	            .sum()
413	    }
414	
415	    /// What the MHPCO will pay out over the whole life of this policy. The cap is
416	    /// read off the insurance sum alone: premium modifiers rate the contract and
417	    /// do not raise the cap.
418	    fn payout_cap(items: &[Item]) -> u64 {
419	        CAP_MULTIPLE * Self::insurance_sum(items)
420	    }
421	
422	    /// The insured items that answer for the damages of one incident, in the
423	    /// order the damages were reported. Assigning coverage for the whole
424	    /// incident at once is what lets the MHPCO hold each insured item to at most
425	    /// one damage, and so notice an incident that over-reports a type.
426	    fn covering_items(&self, damages: &[Damage]) -> Result<Vec<&Item>, String> {
427	        let mut ledger = CoverageLedger::for_incident();
428	        damages
429	            .iter()
430	            .map(|damage| ledger.assign(self, damage).map(|index| &self.items[index]))
431	            .collect()
432	    }
433	
434	    /// What the MHPCO reimburses for a whole incident, as an exact fraction: each
435	    /// damaged item reimbursed under the clauses of the insured item that answers
436	    /// for it. This is the incident-level amount the MHPCO recognises, before it
437	    /// is settled into the amount paid out.
438	    fn reimbursed_total(&self, damages: &[Damage]) -> Result<f64, String> {
439	        let covering = self.covering_items(damages)?;
440	        Ok(damages
441	            .iter()
442	            .zip(covering)
443	            .map(|(damage, insured)| damage.reimbursement(insured))
444	            .sum())
445	    }
446	
447	    /// The MHPCO's cap clause, applied to one settled amount: the cap limits what
448	    /// the policy pays out over its whole life, so an amount the MHPCO would
449	    /// otherwise pay is reduced to whatever cap is left, and what it does pay
450	    /// draws the cap down. The clause reads the already-settled whole-G amount --
451	    /// the cap is stated in whole G and limits the payout, not the reimbursement
452	    /// behind it.
453	    fn pay_within_cap(&mut self, settled: u64) -> u64 {
454	        let payout = settled.min(self.remaining_cap);
455	        self.remaining_cap -= payout;
456	        payout
457	    }
458	
459	    /// The MHPCO settles an incident against this policy: it reimburses the
460	    /// incident under the policy's clauses, settles that total into whole G, and
461	    /// pays it out so far as the policy's cap still allows.
462	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
463	        let reimbursed = self.reimbursed_total(damages)?;
464	        let payout = self.pay_within_cap(settled_payout(reimbursed));
465	        Ok(Settlement {
466	            payout,
467	            remaining_cap: self.remaining_cap,
468	        })
469	    }
470	}
